stage_a_raw:
{
  "decisions": [
    {
      "decision": "flow_variable_domain",
      "evidence": "Demand of Each Retail Store (in units) ... Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"fulfill the demand at each retail store\"",
      "options": [
        "sum_i x[i,j] >= demand[j]",
        "sum_i x[i,j] = demand[j]"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "max_open_centers_constraint",
      "evidence": "\"considering opening up to eight different distribution centers\"",
      "options": [
        "include sum_i y[i] <= 8",
        "omit the constraint (redundant since there are only 8 centers)"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "include sum_i y[i] <= 8"
    },
    {
      "decision": "capacity_linking_form",
      "evidence": "\"each center comes with its own set of opening costs and has a specific capacity limit\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] and x[i,j] <= capacity[i]*y[i] separately"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "\"Opening Costs for Each Distribution Center (in dollars)\" and \"Transportation Cost Per Unit ... (in dollars)\"",
      "options": [
        "total cost in dollars (opening + per-unit transport * units)",
        "total cost in thousands of dollars"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "total cost in dollars (opening + per-unit transport * units)"
    },
    {
      "decision": "transport_cost_matrix_orientation",
      "evidence": "\"Transportation Cost Per Unit from Each Distribution Center to Retail Stores\"",
      "options": [
        "rows = distribution centers, columns = retail stores (trans_cost[i][j])",
        "rows = retail stores, columns = distribution centers (trans_cost[j][i])"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "rows = distribution centers, columns = retail stores (trans_cost[i][j])"
    }
  ]
}
